function e(a){switch(a){case"borrador":return"neutral";case"emitida":return"info";case"recibida":return"success";case"cancelada":return"danger"}}function r(a){switch(a){case"borrador":return"BORRADOR";case"emitida":return"EMITIDA";case"recibida":return"RECIBIDA";case"cancelada":return"CANCELADA"}}function n(a){switch(a){case"ENTREGADA":return"success";case"PARCIAL":return"warning";case"NO_ENTREGADA":return"neutral"}}function c(a){switch(a){case"ENTREGADA":return"Entregada";case"PARCIAL":return"Parcial";case"NO_ENTREGADA":return"No entregada"}}export{c as a,n as b,e as c,r};
